			var centerProj: vec4f = uniform.matrix_projection * centerView;
			centerProj.z = clamp(centerProj.z, 0.0, abs(centerProj.w));
			center.proj = centerProj;
			center.projMat00 = uniform.matrix_projection[0][0];
